import {renderPassportReview} from './coastal-passport-review.js';
import {installPassportFit} from './coastal-passport-fit.js';
import {regions,vehicleLabels} from './coastal-geography.js';
import {countryQuestions} from './coastal-learning.js';
import {lineColour,lineName,freeLineSlot} from './coastal-lines.js';
export function installNetworkFeatures({root,map,side,controls,celebration,state,node,refresh,draw,engine,openVehicle,openCards,fresh}){
 const {stops,lineStops,routeCost,buyLine,extendLine,passengerJourney,roundReview,buyLineVehicle,lineVehicles}=engine;
 const makeButton=(label,action)=>{const b=node('button',label);b.type='button';b.onclick=action;return b;};
 function dialog(title){const d=node('dialog',null,'coastal-shop coastal-network-shop'),close=makeButton('Close '+title.toLowerCase()+' ×',()=>d.close());d.setAttribute('aria-label',title);d.append(close);root.append(d);let resume=false;d.addEventListener('close',()=>{if(!keepPreview)preview=null;keepPreview=false;if(resume&&!state.complete&&!state.failed&&!root.querySelector('dialog[open]'))state.running=true;resume=false;refresh();});return {d,open(){resume=state.running;state.running=false;refresh();d.showModal();}};}
 let preview=null,keepPreview=false;
 const mode=node('dialog',null,'coastal-shop coastal-mode-shop');mode.setAttribute('aria-label','Choose game mode');mode.addEventListener('cancel',e=>e.preventDefault());mode.append(node('h3','Choose your journey'),node('p','Both modes include geography quizzes, expanding maps and round cards.'));
 for(const [id,icon,title,description]of [['normal','☀','Normal','Build your network at the usual pace. No geography disruptions.'],['hard','🌧','Hard','Prepare for temporary floods, sea fog and festival crowds from round 3. Events give 12 seconds of warning.']]){const b=makeButton('',()=>{state.mode=id;state.event=null;mode.close();refresh();});b.dataset.mode=id;b.append(node('span',icon),node('strong',title),node('p',description));mode.append(b);}root.append(mode);
 const modeLabel=node('span',null,'coastal-mode-label');controls.append(modeLabel);
 const eventBox=node('section',null,'coastal-event-notice');eventBox.setAttribute('aria-live','polite');side.prepend(eventBox);
 const planner=dialog('Line planner'),planContent=node('div');planner.d.append(planContent);let plan=[],planType='road',extension=null;
 function renderPlan(){planContent.replaceChildren(node('h3',extension===null?'Plan a multi-stop line':'Extend your line'),node('p','Vehicles travel along the entire line and turns at the ends, or circulates around a closed loop. Choose the first stop again after at least three different stops to close a loop. Each section costs '+routeCost(state,planType)+' 💷. Road crossings and water rules still apply.'));const chain=node('div',null,'coastal-line-chain');chain.textContent=plan.length?plan.map(id=>stops[id].name).join(' → '):'Choose your first stop';planContent.append(chain);const choices=node('div',null,'coastal-line-stops');for(const id of state.activeStops){const b=makeButton(stops[id].name,()=>{plan.push(id);renderPlan();});const closed=plan.length>=4&&plan[0]===plan.at(-1);b.disabled=closed||(plan.includes(id)&&!(plan.length>=3&&id===plan[0]));choices.append(b);}planContent.append(choices);const feedback=node('p',null,'coastal-plan-feedback'),count=extension===null?Math.max(0,plan.length-1):Math.max(0,plan.length-lineStops(state.links[extension]).length),purchase=makeButton('Build '+count+' section'+(count===1?'':'s')+' · '+count*routeCost(state,planType)+' 💷',()=>{let issue;if(extension===null)issue=buyLine(state,plan,planType);else{const trial=structuredClone(state),old=lineStops(trial.links[extension]).length;for(const id of plan.slice(old)){issue=extendLine(trial,extension,id);if(issue)break;}if(!issue){state.links=trial.links;state.credits=trial.credits;}}if(issue){feedback.textContent=issue.message+' '+(issue.hint??'');return;}if(extension===null)state.lineSlot=state.links.at(-1).slot;planner.d.close();refresh();});purchase.disabled=count===0;planContent.append(feedback,makeButton('Undo last stop',()=>{const min=extension===null?0:lineStops(state.links[extension]).length;if(plan.length>min)plan.pop();renderPlan();}),purchase);}
 const planButton=makeButton('Plan a line',()=>{extension=null;state.lineSlot=freeLineSlot(state);planType=state.tool;if(planType==='tunnel')planType='road';plan=[];renderPlan();planner.open();});controls.append(planButton);
 const inspector=dialog('Route performance'),inspectorContent=node('div');inspector.d.append(inspectorContent);
 function inspectLine(index){const link=state.links[index];if(!link)return;state.lineSlot=link.slot;state.tool=link.type;const stats=link.stats??{delivered:0,credits:0,travel:0,service:0,boarded:0};inspectorContent.replaceChildren(node('h3',lineName(link.slot)+' · '+vehicleLabels[link.type]),node('div',lineStops(link).map(id=>stops[id].name).join(' → '),'coastal-line-chain'),node('p',(lineStops(link).length>=4&&lineStops(link)[0]===lineStops(link).at(-1)?'Loop service · '+(lineStops(link).length-1):'Line service · '+lineStops(link).length)+' stops · '+lineVehicles(link).reduce((count,v)=>count+v.cargo.length,0)+' onboard'));const grid=node('dl',null,'coastal-vehicle-stats');for(const [label,value]of [['Delivered this round',stats.delivered],['Fare 💷 earned',stats.credits],['Boardings',stats.boarded],['Travelling',Math.round(stats.travel)+'s'],['Boarding / unloading',Math.round(stats.service)+'s']])grid.append(node('dt',label),node('dd',String(value)));inspectorContent.style.setProperty('--line-colour',lineColour(link.slot));inspectorContent.classList.add('coastal-line-panel');inspectorContent.append(grid,node('p','Figures cover this round. Boarding time includes transfers; fares are earned when a passenger reaches their matching shape.'));if(link.type!=='tunnel'&&lineStops(link)[0]!==lineStops(link).at(-1))inspectorContent.append(makeButton('Extend line · '+routeCost(state,link.type)+' 💷 per section',()=>{inspector.d.close();extension=index;planType=link.type;plan=[...lineStops(link)];renderPlan();setTimeout(()=>planner.open(),0);}));const actions=node('div',null,'coastal-route-vehicle-actions'),purchase=makeButton('Buy '+vehicleLabels[link.type]+' · '+routeCost(state,link.type)+' 💷',()=>{if(buyLineVehicle(state,index)){refresh();inspectLine(index);}});purchase.dataset.buyLineVehicle=String(index);purchase.disabled=state.credits<routeCost(state,link.type);purchase.title=purchase.disabled?'Not enough 💷. Deliver passengers or answer geography coins to earn more.':'Add another vehicle to this line, using your current vehicle upgrades.';actions.append(makeButton('Vehicle upgrades',()=>{inspector.d.close();setTimeout(()=>openVehicle(link.type),0);}),purchase);inspectorContent.append(node('p',lineVehicles(link).length+' vehicle'+(lineVehicles(link).length===1?'':'s')+' on this line · Extra vehicles share your fleet upgrades.'),actions);const spacing=makeButton(link.autoSpacing?'✓ Automatic spacing on':'Enable automatic spacing',()=>{link.autoSpacing=!link.autoSpacing;inspectLine(index);});spacing.setAttribute('aria-pressed',String(Boolean(link.autoSpacing)));inspectorContent.append(spacing,node('p','Spacing holds departures briefly at stops when another vehicle is just ahead. Reverse requests take effect at the next stop; passengers remain onboard.'));lineVehicles(link).forEach((v,i)=>{const row=node('div',null,'coastal-vehicle-control');row.append(node('span',vehicleLabels[link.type]+' '+(i+1)+' · '+(v.direction===1?'outbound':'inbound')),makeButton(v.reversePending?'Cancel reverse request':'Reverse at next stop',()=>{v.reversePending=!v.reversePending;inspectLine(index);}));inspectorContent.append(row);});if(!inspector.d.open)inspector.open();else refresh();}
 const journey=dialog('Passenger journey'),journeyContent=node('div');journey.d.append(journeyContent);
 function inspectPassenger(id){const p=state.passengers[id];if(!p||p.mode==='delivered')return;preview=passengerJourney(state,p);journeyContent.replaceChildren(node('h3','Passenger journey'),node('p','Destination symbol: '+stops[p.destination].shape+' · '+Math.round(p.wait??0)+' seconds waiting'));if(!preview)journeyContent.append(node('p','No connected journey yet. Build a route to a matching destination symbol.'));else{journeyContent.append(node('div',preview.route.map(id=>stops[id].name).join(' → '),'coastal-line-chain'),node('p',preview.transfers.length?preview.transfers.length+' transfer'+(preview.transfers.length===1?'':'s')+' · Change at '+preview.transfers.map(id=>stops[id].name).join(', '):'Direct service: stay on the same line.'));const list=node('ol');for(const leg of preview.legs)list.append(node('li',lineName(state.links[leg.line].slot)+' · '+vehicleLabels[leg.type]+': '+stops[leg.a].name+' → '+stops[leg.b].name));journeyContent.append(list);}journeyContent.append(makeButton('Show journey on map',()=>{keepPreview=true;journey.d.close();draw();}));if(!journey.d.open)journey.open();else refresh();}
 const journeys=makeButton('Passenger journeys',()=>{journeyContent.replaceChildren(node('h3','Choose a waiting passenger'));for(const p of state.passengers.filter(p=>p.mode==='waiting'||p.mode==='boarding'))journeyContent.append(makeButton(stops[p.at].name+' · '+stops[p.destination].shape+' · '+Math.round(p.wait??0)+'s',()=>inspectPassenger(p.id)));if(!state.passengers.some(p=>p.mode==='waiting'||p.mode==='boarding'))journeyContent.append(node('p','No passengers are waiting. Tap a passenger symbol on the map during play.'));journeyContent.append(makeButton('Show journey on map',()=>{keepPreview=true;journey.d.close();draw();}));if(!journey.d.open)journey.open();else refresh();});side.append(journeys);
 const review=dialog('Round review'),reviewContent=node('div');review.d.append(reviewContent);review.d.classList.add('coastal-passport-shop');review.d.firstElementChild.classList.add('coastal-passport-close');review.d.firstElementChild.textContent='×';review.d.firstElementChild.setAttribute('aria-label','Close round review ×');
 const passportFit=installPassportFit(review.d);
 review.d.addEventListener('close',()=>{if(state.complete&&['good','bad'].includes(state.cardPhase))openCards?.();});
 function openReview(){const r=roundReview(state),region=regions.filter(r=>r.round<=state.round).at(-1).id,q=countryQuestions(region)[state.round%3];renderPassportReview({content:reviewContent,state,review:r,region,question:q,stops,lineStops,node,makeButton,refresh,close:()=>review.d.close()});review.open();}

 const clearHighlight=makeButton('Clear journey highlight',()=>{preview=null;refresh();});side.append(clearHighlight,makeButton('Network review',openReview));celebration.append(makeButton('Review this round',()=>{celebration.hidden=true;openReview();}));
 function refreshFeatures(){clearHighlight.hidden=!preview;modeLabel.textContent=state.mode==='hard'?'Hard mode':'Normal mode';const e=state.event,visible=state.mode==='hard'&&e&&state.elapsed>=e.warningAt&&state.elapsed<e.end;eventBox.hidden=!visible;if(visible){const active=state.elapsed>=e.start;eventBox.dataset.active=String(active);eventBox.replaceChildren(node('strong',(active?'⚠ Active: ':'⚠ Coming: ')+e.title),node('p',(active?'Ends in '+Math.ceil(e.end-state.elapsed)+'s':'Starts in '+Math.ceil(e.start-state.elapsed)+'s')+' · '+e.advice),node('small','Geography: '+e.fact));}}
 return {inspectLine,inspectPassenger,destroy(){passportFit.destroy();},refresh:refreshFeatures,get preview(){return preview;},chooseMode(){state.running=false;mode.showModal();},start(){if(fresh)queueMicrotask(()=>{if(root.isConnected)mode.showModal();});refreshFeatures();}};
}
